import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"23、【剥】 坤下艮上","description":"周易口诀义 - 23、【剥】 坤下艮上","frontmatter":{"title":"23、【剥】 坤下艮上","description":"周易口诀义 - 23、【剥】 坤下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/025.md","filePath":"zh/classics/koujueyi/025.md"}'),r={name:"zh/classics/koujueyi/025.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_23、【剥】-坤下艮上" tabindex="-1">23、【剥】 坤下艮上 <a class="header-anchor" href="#_23、【剥】-坤下艮上" aria-label="Permalink to “23、【剥】 坤下艮上”">​</a></h1><p>彖曰：剥，剥也，柔变刚也。「不利有攸往」，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。</p><p>象曰：山附于地，剥。上以厚下安宅。</p><p>初六：剥床以足，蔑贞凶。</p><p>象曰：「剥床以足」，以灭下也。</p><p>六二：剥床以辨，蔑贞凶。</p><p>象曰：「剥床以辨」，未有与也。</p><p>六三：剥之无咎。</p><p>象曰：「剥之无咎」，失上下也。</p><p>六四：剥床以肤，凶。</p><p>象曰：「剥床以肤」，切近灾也。</p><p>六五：贯鱼以宫人宠，无不利。</p><p>象曰：「以宫人宠」，终无尤也。</p><p>上九，硕果不食，君子得舆，小人剥庐。</p><p>象曰：「君子得舆」，民所载也。「小人剥庐」，终不可用也。</p><p>解读</p><p>「剥，不利有攸往」者，剥，落也。以阴剥阳，以小人损君子，是小人道长，君子道消，小人侵害君子，故君子「不利有攸往」。象曰「山附于地，剥」者，山本高峻，今附于地，是剥落之象也。「上以厚下安宅」者，宅，人居者也。剥之为体，自下而起为「乾」，从初九而至剥也，即是小人在下而起，上侵于君子，君子即可敦厚为德，制伏下人，各令安其居也。</p><p>初六，剥床以足，蔑贞凶。「蔑」，削也。床者，人所安之物也。今剥道自下而起，似侵剥床足，人渐不安处，削除中正之道，所以「凶」也。</p><p>六二，剥床以辨，蔑，贞凶。是床梐之间、床足之上分辨之处也。剥之渐盛，削不已，至于床梐之间、分辨之处，削去正道，正道陵夷，所以「凶」也。</p><p>六三，剥之无咎。众皆剥阳，唯六三与上九相应，是独亲狎于君子，虽当剥时，可以「无咎」也。</p><p>六四：剥床以肤，凶。床既削尽，以至人肤，身体被其侵剥，切近于灾，故为「凶」矣。</p><p>六五：贯鱼以宫人宠，无不利者，独处于尊，为剥之主，众阴皆归，骈头相次，如贯穿之鱼。小人得宠，以消君子。若接待众阴，而似宫人在内，未能害于外政矣。既不预政事，故云「无不利」也。</p><p>上九：硕果不食，君子得舆，小人剥庐者，处剥之上，独处不落，犹「硕果」之不食。若君子处于此位，似车舆运载下人，令其获安，故云君子得舆，民所载也。小人处此上位，即侵削下人庐舍，民何以安？故曰「小人不可用为君长」，故曰「小人剥庐，终不可用」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
